package com.seolhwa.armyrist

internal object PortableCryptoLimits {
    const val CURRENT_ITERATIONS = 600_000
    // Includes all files generated by format v1, while bounding untrusted work.
    const val MAX_ITERATIONS = 600_000

    fun validate(iterations: Int, saltBytes: Int, ivBytes: Int) {
        require(iterations in 1..MAX_ITERATIONS) { "Unsupported KDF work factor." }
        require(saltBytes in 16..64) { "Invalid KDF salt." }
        require(ivBytes == 12) { "Invalid GCM IV." }
    }
}
